export const isSceneCovered = (tx: number, ty: number): boolean =>
  ty >= 0 &&
  ty < HD_SCENE_COVERAGE.length &&
  tx >= 0 &&
  tx < HD_SCENE_COVERAGE[ty].length &&
  HD_SCENE_COVERAGE[ty][tx] === '1';
